import{_ as s,H as n,f as t,i}from"./chunks/framework.nyB-Xt5O.js";const g=JSON.parse('{"title":"Dashboard 设计","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-map/km-6-bi-visualization/03-dashboard-design.md","filePath":"knowledge-map/km-6-bi-visualization/03-dashboard-design.md","lastUpdated":1779798726000}'),l={name:"knowledge-map/km-6-bi-visualization/03-dashboard-design.md"};function e(o,a,r,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="dashboard-设计" tabindex="-1">Dashboard 设计 <a class="header-anchor" href="#dashboard-设计" aria-label="Permalink to &quot;Dashboard 设计&quot;">​</a></h1><blockquote><p>Dashboard（仪表板）是数据分析的<strong>终端输出</strong>，所有数据清洗、建模、计算工作最终都要通过仪表板呈现在决策者面前。好的仪表板让信息一目了然，差的仪表板让用户迷失在数据中。</p></blockquote><h2 id="信息层级-information-hierarchy" tabindex="-1">信息层级（Information Hierarchy） <a class="header-anchor" href="#信息层级-information-hierarchy" aria-label="Permalink to &quot;信息层级（Information Hierarchy）&quot;">​</a></h2><p>Dashboard 的设计遵循 <strong>F 型扫描模式</strong>（F-pattern）或 <strong>Z 型扫描模式</strong>（Z-pattern），读者视线从左上向右下移动。因此，信息重要度从左到右、从上到下递减。</p><h3 id="三层层级结构" tabindex="-1">三层层级结构 <a class="header-anchor" href="#三层层级结构" aria-label="Permalink to &quot;三层层级结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  █████████████ 顶部导航栏 / 筛选器 █████████  │</span></span>
<span class="line"><span>│  ══════════════════════════════════════════ │</span></span>
<span class="line"><span>│  ▊ 关键 KPI 行    ▊       ▊       ▊        │</span></span>
<span class="line"><span>│  ▊ 总营收 2.3B    ▊ 毛利 45% ▊ 客户数 1.2M  │</span></span>
<span class="line"><span>│  ▊ YoY +12.3%    ▊ +2.1%   ▊ +8.7%         │</span></span>
<span class="line"><span>│  ══════════════════════════════════════════ │</span></span>
<span class="line"><span>│  ┌──────────┐ ┌───────────────────────────┐ │</span></span>
<span class="line"><span>│  │ 主图表     │ │ 辅助分析面板              │ │</span></span>
<span class="line"><span>│  │ (核心指标  │ │ (明细表 / 下钻详情)       │ │</span></span>
<span class="line"><span>│  │  趋势图)   │ │                          │ │</span></span>
<span class="line"><span>│  └──────────┘ └───────────────────────────┘ │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>第一层 — 概览层（Executive Summary）</strong>：3-6 个核心 KPI，展示业务健康度的整体状态。通常在最上方一行。</p><p><strong>第二层 — 分析层（Analytical Layer）</strong>：核心图表和趋势，回答&quot;发生了什么&quot;和&quot;趋势如何&quot;。占据 60% 以上的面积。</p><p><strong>第三层 — 明细层（Detail Layer）</strong>：详细数据表格、下钻详情、原始记录，供需要深入调查的用户使用。</p><div class="tip custom-block"><p class="custom-block-title">设计原则</p><p>Dashboard 的设计目标是让用户在 <strong>5 秒内</strong> 理解当前的业务状态（概览层）， <strong>30 秒内</strong> 发现关键趋势或异常（分析层）， <strong>5 分钟内</strong> 找到原因（明细层/交互下钻）。</p></div><h2 id="kpi-布局规则" tabindex="-1">KPI 布局规则 <a class="header-anchor" href="#kpi-布局规则" aria-label="Permalink to &quot;KPI 布局规则&quot;">​</a></h2><h3 id="单值-kpi-卡片" tabindex="-1">单值 KPI 卡片 <a class="header-anchor" href="#单值-kpi-卡片" aria-label="Permalink to &quot;单值 KPI 卡片&quot;">​</a></h3><p>每个 KPI 卡片应包含以下核心信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│ 客户获取成本 (CAC)          │  ← 指标名称</span></span>
<span class="line"><span>│                ¥ 328         │  ← 当前值（大字号）</span></span>
<span class="line"><span>│  ¥ ▲  5.2%  vs 上月          │  ← 变化方向和幅度</span></span>
<span class="line"><span>│       目标值 ¥ 350   ✓       │  ← 目标达成状态</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span></code></pre></div><p><strong>布局规范</strong>：</p><ul><li>指标名称在上方，用小字号（次级信息）</li><li>当前值居中，用大字号（首要信息）</li><li>变化方向和目标对比在下方，用更小字号</li><li>使用颜色语义：红色 = 恶化，绿色 = 改善（或反向，根据业务而定）</li></ul><h3 id="kpi-组织方式" tabindex="-1">KPI 组织方式 <a class="header-anchor" href="#kpi-组织方式" aria-label="Permalink to &quot;KPI 组织方式&quot;">​</a></h3><ul><li><strong>按主题分组</strong>：营收相关放一起，客户相关放一起</li><li><strong>按因果关系</strong>：领先指标（Leading Indicators）在前，滞后指标（Lagging Indicators）在后</li><li><strong>按频率分组</strong>：实时指标与日报指标分开展示</li></ul><h2 id="执行型-vs-运营型-dashboard" tabindex="-1">执行型 vs 运营型 Dashboard <a class="header-anchor" href="#执行型-vs-运营型-dashboard" aria-label="Permalink to &quot;执行型 vs 运营型 Dashboard&quot;">​</a></h2><p>两种 Dashboard 的设计逻辑有本质区别，不能混为一谈。</p><table tabindex="0"><thead><tr><th>维度</th><th>执行型（Executive）</th><th>运营型（Operational）</th></tr></thead><tbody><tr><td>目标用户</td><td>C-level, VP, 总监</td><td>一线分析师、运营人员</td></tr><tr><td>核心问题</td><td>&quot;业务健康度如何？&quot;</td><td>&quot;下一步该做什么？&quot;</td></tr><tr><td>刷新频率</td><td>每日/每周</td><td>实时/每小时</td></tr><tr><td>交互深度</td><td>被动浏览，少交互</td><td>主动分析，深度交互</td></tr><tr><td>图表数量</td><td>5-8 个</td><td>10-20 个</td></tr><tr><td>设计风格</td><td>简洁、大气、空间充足</td><td>信息密度高，工具化</td></tr><tr><td>数据粒度</td><td>聚合级（月度/周度）</td><td>明细级（日度/实时）</td></tr><tr><td>异常处理</td><td>标记异常，引导下钻</td><td>实时告警，直接触发行动</td></tr></tbody></table><h3 id="执行型-dashboard-最佳实践" tabindex="-1">执行型 Dashboard 最佳实践 <a class="header-anchor" href="#执行型-dashboard-最佳实践" aria-label="Permalink to &quot;执行型 Dashboard 最佳实践&quot;">​</a></h3><ul><li><strong>先给结论</strong>：每个图表的上方用一句话总结核心洞察</li><li><strong>少即是多</strong>：屏幕上的每一个元素都要问自己&quot;如果去掉它，决策者会漏掉什么？&quot;</li><li><strong>对比是核心</strong>：把实际值与目标值、上月、去年同期的对比放在显眼位置</li><li><strong>KPI 数量限制</strong>：不超过 7±2 个核心指标（Miller&#39;s Law）</li></ul><h3 id="运营型-dashboard-最佳实践" tabindex="-1">运营型 Dashboard 最佳实践 <a class="header-anchor" href="#运营型-dashboard-最佳实践" aria-label="Permalink to &quot;运营型 Dashboard 最佳实践&quot;">​</a></h3><ul><li><strong>可操作性</strong>：每个指标都应该有对应的操作路径</li><li><strong>实时反馈</strong>：数据更新后立即反映在界面上</li><li><strong>告警机制</strong>：设定阈值，触发后自动标注/通知</li><li><strong>导出功能</strong>：支持导出原始数据做进一步分析</li></ul><h2 id="交互设计-interaction-design" tabindex="-1">交互设计（Interaction Design） <a class="header-anchor" href="#交互设计-interaction-design" aria-label="Permalink to &quot;交互设计（Interaction Design）&quot;">​</a></h2><h3 id="下钻-drill-down" tabindex="-1">下钻（Drill-Down） <a class="header-anchor" href="#下钻-drill-down" aria-label="Permalink to &quot;下钻（Drill-Down）&quot;">​</a></h3><p>用户点击某个数据元素后，进入更细粒度的视图。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下钻层级设计示例：</span></span>
<span class="line"><span>  年度营收（全国总览）</span></span>
<span class="line"><span>   → 季度营收（按区域）</span></span>
<span class="line"><span>    → 月度营收（按省份）</span></span>
<span class="line"><span>     → 日报营收（按城市/门店）</span></span></code></pre></div><p><strong>实现要点</strong>：</p><ul><li>每次下钻都显示当前路径（Breadcrumb），支持一键返回</li><li>下钻后保留上下文，不要完全切换页面</li><li>提供&quot;返回上层&quot;和&quot;重置&quot;按钮</li></ul><h3 id="筛选与参数控制-filtering" tabindex="-1">筛选与参数控制（Filtering） <a class="header-anchor" href="#筛选与参数控制-filtering" aria-label="Permalink to &quot;筛选与参数控制（Filtering）&quot;">​</a></h3><p>合理的筛选设计是 Dashboard 可用性的关键：</p><ul><li><strong>全局筛选器（Global Filter）</strong>：影响整个 Dashboard，放在顶部</li><li><strong>上下文筛选（Contextual Filter）</strong>：只影响特定图表，放在图表附近</li><li><strong>联动筛选（Cross-Filtering）</strong>：点击一个图表的数据点，其他图表联动更新</li></ul><h3 id="交叉筛选-cross-filtering-brushing" tabindex="-1">交叉筛选（Cross-Filtering / Brushing） <a class="header-anchor" href="#交叉筛选-cross-filtering-brushing" aria-label="Permalink to &quot;交叉筛选（Cross-Filtering / Brushing）&quot;">​</a></h3><p>用户选中某个图表中的部分数据，其他图表同步高亮同一维度。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击 &quot;华东&quot; 区域 →</span></span>
<span class="line"><span>  营收趋势图：只高亮华东曲线</span></span>
<span class="line"><span>  区域占比图：高亮华东对应的扇形</span></span>
<span class="line"><span>  客户分布图：只显示华东城市</span></span>
<span class="line"><span>  明细表：筛选出华东的交易记录</span></span></code></pre></div><p><strong>设计原则</strong>：</p><ul><li>被选中的状态要清晰可辨（颜色变化 + 高亮）</li><li>提供一键清除所有筛选</li><li>显示当前处于筛选状态中的维度数量和占比</li></ul><h3 id="悬停提示-tooltip" tabindex="-1">悬停提示（Tooltip） <a class="header-anchor" href="#悬停提示-tooltip" aria-label="Permalink to &quot;悬停提示（Tooltip）&quot;">​</a></h3><p>Tooltip 是提供额外信息的重要手段，但不应承载关键信息。</p><p><strong>好的 Tooltip 设计</strong>：</p><ul><li>显示精确数值（图表中无法显示的精度）</li><li>提示数据的定义或来源（如&quot;销售额 = 含税金额&quot;）</li><li>显示样本量（n=xxx），帮助判断可靠性</li><li>不超过 3-4 行信息</li></ul><h2 id="性能与加载策略" tabindex="-1">性能与加载策略 <a class="header-anchor" href="#性能与加载策略" aria-label="Permalink to &quot;性能与加载策略&quot;">​</a></h2><ul><li><strong>按需加载</strong>：初始只加载概览层数据，分析层和明细层在用户滚动或点击时加载</li><li><strong>数据缓存</strong>：相同时间粒度的查询结果缓存到内存</li><li><strong>限制数据量</strong>：前端展示的数据点不应超过 1000 个，超过则做聚合采样</li><li><strong>渐进式加载</strong>：先显示骨架屏（Skeleton Screen），再填充数据</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/01-principles">可视化原理</a> — 格式塔原则在 Dashboard 布局中的应用</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/02-chart-types">图表类型详解</a> — 选择正确的图表类型</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/04-storytelling">Data Storytelling</a> — 用数据讲述故事</li></ul>`,47)])])}const u=s(l,[["render",e]]);export{g as __pageData,u as default};
